<include file="Public:header"/><div class="mainbox">    <div id="nav" class="mainnav_title">        <ul>            <a href="{pigcms{:U('Employee/write_field',array('cat_id'=>$now_category['cat_id']))}" class="on">填写项列表</a>|            <a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Employee/write_field_add',array('cat_id'=>$now_category['cat_id']))}','添加填写项',460,250,true,false,false,addbtn,'add',true);">添加填写项</a>        </ul>    </div>    <form name="myform" id="myform" action="" method="post">        <div class="table-list">            <table width="100%" cellspacing="0">                <colgroup>                    <col width="40"/>                    <col/>                    <col width="80"/>                    <col width="40"/>                    <col width="140"/>                    <col width="120"/>                    <col width="100" align="center"/>                </colgroup>                <thead>                <tr>                    <th>排序</th>                    <th>名称</th>                    <th>类型</th>                    <th>必填</th>                    <th>说明</th>                    <th>是否前端显示</th>                    <th class="textcenter">操作</th>                </tr>                </thead>                <tbody>                <if condition="is_array($write_group_info)">                    <volist name="write_group_info" id="item">                        <tr style="color: #F58444;font-weight: bold;"><td colspan="7">{pigcms{$item['gname']}  字段<td/></tr>                        <php>if (!empty($item['write_info'])){</php>                            <volist name="item['write_info']" id="vo">                            <tr>                                <td>{pigcms{$vo.sort}</td>                                <td>{pigcms{$vo.name}</td>                                <td>                                    <if condition="$vo['type'] eq 1">多行                                        <elseif condition="$vo['type'] eq 2"/>地图                                        <elseif condition="$vo['type'] eq 3"/>下拉框                                        <elseif condition="$vo['type'] eq 4"/>数字                                        <elseif condition="$vo['type'] eq 5"/>邮件                                        <elseif condition="$vo['type'] eq 6"/>日期                                        <elseif condition="$vo['type'] eq 7"/>时间                                        <elseif condition="$vo['type'] eq 8"/>日期时间                                        <elseif condition="$vo['type'] eq 9"/>手机                                        <elseif condition="$vo['type'] eq 10"/>图片                                        <elseif condition="$vo['type'] eq 11"/>单选                                        <elseif condition="$vo['type'] eq 12"/>单图                                        <else/>单行                                    </if>                                </td>                                <td>                                    <if condition="$vo['iswrite'] eq 1">是<else/>否</if>                                </td>                                <td>                                    {pigcms{$vo.des}                                </td>                                <td>                                    <if condition="$vo['no_hide'] neq 1">                                        <span class="cb-enable"><label class="cb-enable <if condition="$vo['is_show'] eq 1">selected</if>"><span  onclick="showWitch('{pigcms{$now_category['cat_id']}', '{pigcms{$vo.name}', 1)" >显示</span><input type="radio" value="0" <if condition="$vo['is_show'] eq 1">checked="checked"</if> /></label></span>                                        <span class="cb-disable"><label class="cb-disable <if condition="$vo['is_show'] eq 0">selected</if>"><span  onclick="showWitch('{pigcms{$now_category['cat_id']}', '{pigcms{$vo.name}', 0)">隐藏</span><input type="radio" value="1" <if condition="$vo['is_show'] eq 0">checked="checked"</if> /></label></span>                                    <else/>                                        显示                                    </if>                                </td>                                <td class="textcenter">                                    <if condition="$vo['no_del'] neq 1">                                        <a href="javascript:void(0);" class="delete_row" parameter="cat_id={pigcms{$now_category.cat_id}&name={pigcms{$vo.name}" url="{pigcms{:U('Employee/write_field_del')}">删除</a>                                        | <a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Employee/write_field_edit',array('cat_id'=>$now_category['cat_id'],'name'=>$vo['name']))}','编辑填写项',550,300,true,false,false,editbtn,'edit',true);">编辑</a>                                        <else/>                                        <a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Employee/write_field_edit',array('cat_id'=>$now_category['cat_id'],'name'=>$vo['name']))}','编辑填写项',550,300,true,false,false,editbtn,'edit',true);">编辑</a>                                    </if>                                </td>                            </tr>                            </volist>                        <php>}</php>                    </volist><!--                    <volist name="write_field" id="vo">--><!--                        <tr>--><!--                            <td>{pigcms{$vo.sort}</td>--><!--                            <td>{pigcms{$vo.name}</td>--><!--                            <td>--><!--                                <if condition="$vo['type'] eq 1">多行--><!--                                    <elseif condition="$vo['type'] eq 2"/>地图--><!--                                    <elseif condition="$vo['type'] eq 3"/>下拉框--><!--                                    <elseif condition="$vo['type'] eq 4"/>数字--><!--                                    <elseif condition="$vo['type'] eq 5"/>邮件--><!--                                    <elseif condition="$vo['type'] eq 6"/>日期--><!--                                    <elseif condition="$vo['type'] eq 7"/>时间--><!--                                    <elseif condition="$vo['type'] eq 8"/>日期时间--><!--                                    <elseif condition="$vo['type'] eq 9"/>手机--><!--                                    <elseif condition="$vo['type'] eq 10"/>图片--><!--                                    <elseif condition="$vo['type'] eq 11"/>单选--><!--                                    <elseif condition="$vo['type'] eq 12"/>单图--><!--                                    <else/>单行--><!--                                </if>--><!--                            </td>--><!--                            <td>--><!--                                <if condition="$vo['iswrite'] eq 1">是<else/>否</if>--><!--                            </td>--><!--                            <td>--><!--                                {pigcms{$vo.des}--><!--                            </td>--><!----><!--                            <td>--><!--                                <if condition="$vo['no_hide'] neq 1">--><!--                                    <span class="cb-enable"><label class="cb-enable <if condition="$vo['is_show'] eq 1">selected</if>"><span  onclick="showWitch('{pigcms{$now_category['cat_id']}', '{pigcms{$vo.name}', 1)" >显示</span><input type="radio" value="0" <if condition="$vo['is_show'] eq 1">checked="checked"</if> /></label></span>--><!--                                    <span class="cb-disable"><label class="cb-disable <if condition="$vo['is_show'] eq 0">selected</if>"><span  onclick="showWitch('{pigcms{$now_category['cat_id']}', '{pigcms{$vo.name}', 0)">隐藏</span><input type="radio" value="1" <if condition="$vo['is_show'] eq 0">checked="checked"</if> /></label></span>--><!--                                    <else/>--><!--                                    显示--><!--                                 </if>--><!--                              </td>--><!--                            <td class="textcenter">--><!--                                <if condition="$vo['no_del'] neq 1">--><!--                                    <a href="javascript:void(0);" class="delete_row" parameter="cat_id={pigcms{$now_category.cat_id}&name={pigcms{$vo.name}" url="{pigcms{:U('Employee/write_field_del')}">删除</a>--><!----><!--                                    | <a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Employee/write_field_edit',array('cat_id'=>$now_category['cat_id'],'name'=>$vo['name']))}','编辑填写项',550,300,true,false,false,editbtn,'edit',true);">编辑</a>--><!--                                    <else/>--><!----><!--                                    <a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Employee/write_field_edit',array('cat_id'=>$now_category['cat_id'],'name'=>$vo['name']))}','编辑填写项',550,300,true,false,false,editbtn,'edit',true);">编辑</a>--><!--                                </if>--><!--                            </td>--><!--                        </tr>--><!--                    </volist>-->                    <else/>                    <tr><td class="textcenter red" colspan="6">自定义选项列表为空！</td></tr>                </if>                </tbody>            </table>        </div>    </form></div><script>    var lockInfo = false;    function showWitch(cat_id, name, status) {        if (lockInfo) return;        lockInfo = true;        console.log('切换信息', cat_id, name, status)        var chat_switch_url = "{pigcms{:U('Employee/write_field_show')}";        $.post(chat_switch_url,{'cat_id': cat_id, 'name': name, 'is_show': status},function(data){            console.log('返回值----------', data);            if (data && (data.status === 1 || data.status === '1')) {                location.reload();            } else {                location.reload();                alert(data.info);            }            lockInfo = false;        },'json');    }</script><include file="Public:footer"/>